<?php
namespace ZinCelestial\Platform\Fleet; defined('ABSPATH')||exit;
final class FleetRepository{const RESULTS='zcp_network_diagnostics';public function summary():array{$rows=(array)get_site_option(self::RESULTS,array());$now=time();$stale=0;$versions=array();foreach($rows as $row){if((int)($row['updated']??0)<$now-DAY_IN_SECONDS)$stale++;$v=(string)($row['platform_version']??'unknown');$versions[$v]=($versions[$v]??0)+1;}return array('discovered'=>count($rows),'stale'=>$stale,'versions'=>$versions,'last_aggregation'=>(array)get_site_option('zcp_aggregation_state',array()));}public function sites(int $page=1,int $per_page=50):array{$rows=array_values((array)get_site_option(self::RESULTS,array()));$offset=(max(1,$page)-1)*max(1,min(100,$per_page));return array_slice($rows,$offset,$per_page);} }
